using System;using System.Data;using System.Data.SqlClient;using System.Collections.Generic;using FindIt.Models;namespace FindIt.DAL{public class ItemRepository{public List<Item> Search(string q,string category,string type,string location,DateTime? date){var list=new List<Item>();using(var c=DatabaseHelper.GetConnection())using(var cmd=new SqlCommand(@"SELECT i.*,u.FullName FROM Items i JOIN Users u ON u.UserId=i.UserId WHERE i.Status<>'Closed' AND (@q='' OR i.Title LIKE @like OR i.Description LIKE @like) AND (@cat='' OR i.Category=@cat) AND (@type='' OR i.ItemType=@type) AND (@loc='' OR i.Location LIKE @loclike) AND (@date IS NULL OR CAST(i.DateOfIncident AS date)=@date) ORDER BY i.CreatedAt DESC",c)){cmd.Parameters.AddWithValue("@q",q??"");cmd.Parameters.AddWithValue("@like","%"+(q??"")+"%");cmd.Parameters.AddWithValue("@cat",category??"");cmd.Parameters.AddWithValue("@type",type??"");cmd.Parameters.AddWithValue("@loc",location??"");cmd.Parameters.AddWithValue("@loclike","%"+(location??"")+"%");cmd.Parameters.Add("@date",SqlDbType.Date).Value=(object)date??DBNull.Value;c.Open();using(var r=cmd.ExecuteReader())while(r.Read())list.Add(Map(r));}return list;}public Item Get(int id){using(var c=DatabaseHelper.GetConnection())using(var cmd=new SqlCommand("SELECT i.*,u.FullName FROM Items i JOIN Users u ON u.UserId=i.UserId WHERE ItemId=@id",c)){cmd.Parameters.AddWithValue("@id",id);c.Open();using(var r=cmd.ExecuteReader())return r.Read()?Map(r):null;}}public int Save(Item i){using(var c=DatabaseHelper.GetConnection())using(var cmd=new SqlCommand(i.ItemId==0?@"INSERT INTO Items(UserId,Title,Description,Category,ItemType,Location,DateOfIncident,ImagePath) VALUES(@uid,@t,@d,@cat,@type,@loc,@date,@img);SELECT SCOPE_IDENTITY();":@"UPDATE Items SET Title=@t,Description=@d,Category=@cat,ItemType=@type,Location=@loc,DateOfIncident=@date,ImagePath=COALESCE(@img,ImagePath) WHERE ItemId=@id AND UserId=@uid;SELECT @id",c)){Params(cmd,i);if(i.ItemId>0)cmd.Parameters.AddWithValue("@id",i.ItemId);c.Open();return Convert.ToInt32(cmd.ExecuteScalar());}}public bool Delete(int id,int uid){using(var c=DatabaseHelper.GetConnection())using(var cmd=new SqlCommand("DELETE FROM Items WHERE ItemId=@id AND UserId=@uid AND Status='Open' AND NOT EXISTS(SELECT 1 FROM Claims WHERE ItemId=@id AND ClaimStatus='Approved')",c)){cmd.Parameters.AddWithValue("@id",id);cmd.Parameters.AddWithValue("@uid",uid);c.Open();return cmd.ExecuteNonQuery()>0;}}public DataTable AllAdmin(string q,string type){using(var c=DatabaseHelper.GetConnection())using(var cmd=new SqlCommand("SELECT i.ItemId,i.Title,i.Category,i.ItemType,i.Location,i.DateOfIncident,i.Status,i.CreatedAt,u.FullName FROM Items i JOIN Users u ON u.UserId=i.UserId WHERE (@q='' OR i.Title LIKE @like OR i.Location LIKE @like) AND (@t='' OR i.ItemType=@t) ORDER BY i.CreatedAt DESC",c)){cmd.Parameters.AddWithValue("@q",q??"");cmd.Parameters.AddWithValue("@like","%"+(q??"")+"%");cmd.Parameters.AddWithValue("@t",type??"");using(var da=new SqlDataAdapter(cmd)){var dt=new DataTable();da.Fill(dt);return dt;}}}public bool AdminDelete(int id){using(var c=DatabaseHelper.GetConnection())using(var cmd=new SqlCommand("DELETE FROM Items WHERE ItemId=@id AND NOT EXISTS(SELECT 1 FROM Claims WHERE ItemId=@id AND ClaimStatus='Approved')",c)){cmd.Parameters.AddWithValue("@id",id);c.Open();return cmd.ExecuteNonQuery()>0;}}public void Close(int id){using(var c=DatabaseHelper.GetConnection())using(var cmd=new SqlCommand("UPDATE Items SET Status='Closed' WHERE ItemId=@id",c)){cmd.Parameters.AddWithValue("@id",id);c.Open();cmd.ExecuteNonQuery();}}public DashboardViewModel Stats(int uid){var d=new DashboardViewModel();using(var c=DatabaseHelper.GetConnection())using(var cmd=new SqlCommand("SELECT (SELECT COUNT(*) FROM Items WHERE ItemType='Lost' AND Status<>'Closed'),(SELECT COUNT(*) FROM Items WHERE ItemType='Found' AND Status<>'Closed'),(SELECT COUNT(*) FROM Items WHERE UserId=@u),(SELECT COUNT(*) FROM Claims WHERE ClaimerId=@u AND ClaimStatus='Pending'),(SELECT COUNT(*) FROM Claims WHERE ClaimerId=@u AND ClaimStatus='Approved')",c)){cmd.Parameters.AddWithValue("@u",uid);c.Open();using(var r=cmd.ExecuteReader())if(r.Read()){d.LostCount=r.GetInt32(0);d.FoundCount=r.GetInt32(1);d.MyReports=r.GetInt32(2);d.PendingClaims=r.GetInt32(3);d.ApprovedClaims=r.GetInt32(4);}}return d;}public DashboardViewModel AdminStats(){var d=new DashboardViewModel();using(var c=DatabaseHelper.GetConnection())using(var cmd=new SqlCommand("SELECT (SELECT COUNT(*) FROM Users WHERE Role='Student'),(SELECT COUNT(*) FROM Items WHERE ItemType='Lost'),(SELECT COUNT(*) FROM Items WHERE ItemType='Found'),(SELECT COUNT(*) FROM Claims WHERE ClaimStatus='Pending'),(SELECT COUNT(*) FROM Claims WHERE ClaimStatus='Approved'),(SELECT COUNT(*) FROM Claims WHERE ClaimStatus='Rejected')",c)){c.Open();using(var r=cmd.ExecuteReader())if(r.Read()){d.Students=r.GetInt32(0);d.LostCount=r.GetInt32(1);d.FoundCount=r.GetInt32(2);d.PendingClaims=r.GetInt32(3);d.ApprovedClaims=r.GetInt32(4);d.RejectedClaims=r.GetInt32(5);}}return d;}private void Params(SqlCommand cmd,Item i){cmd.Parameters.AddWithValue("@uid",i.UserId);cmd.Parameters.AddWithValue("@t",i.Title);cmd.Parameters.AddWithValue("@d",i.Description);cmd.Parameters.AddWithValue("@cat",i.Category);cmd.Parameters.AddWithValue("@type",i.ItemType);cmd.Parameters.AddWithValue("@loc",i.Location);cmd.Parameters.AddWithValue("@date",i.DateOfIncident);cmd.Parameters.AddWithValue("@img",(object)i.ImagePath??DBNull.Value);}private Item Map(SqlDataReader r){return new Item{ItemId=r.GetInt32(0),UserId=r.GetInt32(1),Title=r.GetString(2),Description=r.GetString(3),Category=r.GetString(4),ItemType=r.GetString(5),Location=r.GetString(6),DateOfIncident=r.GetDateTime(7),ImagePath=r.IsDBNull(8)?null:r.GetString(8),Status=r.GetString(9),CreatedAt=r.GetDateTime(10),ReporterName=r.GetString(11)};}}}